class Solution {
  largestSubarraySumMinimized(a, k) {
    let low = Math.max(...a);
    let high = a.reduce((acc, curr) => acc + curr, 0);
    let ans = -1;
    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      const canSplit = this.canSplit(a, k, mid);
      if (canSplit) {
        ans = mid;
        high = mid - 1;
      } else {
        low = mid + 1;
      }
    }
    return ans;
  }

  canSplit(a, k, limit) {
    let load = 0,
      count = 1;
    for (let i = 0; i < a.length; i++) {
      load = load + a[i];
      if (load > limit) {
        count++;
        load = a[i];
      }
    }
    // Same case of Book Allocation Problem
    if (count <= k && a.length >= k) {
      return true;
    }
    return false;
  }
}

